python3 -c "import xarray as xr; import numpy as np; import xskillscore as xs; 
def nmse_test(a, b, dim=None, weights=None, skipna=False, keep_attrs=False, axis=None):
    if not isinstance(a, xr.DataArray) and not isinstance(b, xr.DataArray):
        a_xr = xr.DataArray(a)
        b_xr = xr.DataArray(b)
        if axis is not None:
            if isinstance(axis, int):
                dim = f'dim_{axis}'
            elif isinstance(axis, (list, tuple)):
                dim = [f'dim_{ax}' for ax in axis]
        mse = xs.mse(a_xr, b_xr, dim=dim, weights=weights, skipna=skipna, keep_attrs=keep_attrs)
        var_a = a_xr.var(dim=dim, weights=weights, skipna=skipna)
        res = mse / var_a
        if isinstance(res, xr.DataArray):
            return res.values
        return res
    else:
        mse = xs.mse(a, b, dim=dim, weights=weights, skipna=skipna, keep_attrs=keep_attrs)
        var_a = a.var(dim=dim, weights=weights, skipna=skipna)
        return mse / var_a

a = np.array([1, 2, 3])
b = np.array([1, 3, 2])
print('NMSE Numpy:', nmse_test(a, b))
a_xr = xr.DataArray(a, dims=['x'])
b_xr = xr.DataArray(b, dims=['x'])
print('NMSE Xarray:', nmse_test(a_xr, b_xr, dim='x'))"
